-- ============================================================================
-- SEDIMA Parc — le relevé de transport réel : les voyages, partie 2 sur 3.
--
-- **Ce n'est pas une migration.** Chargement tiré du relevé de tonnage
-- hebdomadaire de la Direction des Opérations (RECAP TONNAGE HEBDOMMADAIRE),
-- du 2026-06-15 au 2026-09-03. Voir docs/RELEVE-TRANSPORT-REEL.md.
--
-- 420 voyages, 9647 t, du 2026-07-14 au 2026-08-17.
--
-- REJOUABLE : `on conflict do nothing`. À jouer **dans l'ordre des fichiers**,
-- les camions d'abord.
-- ============================================================================

on conflict (numero) do nothing;


-- Vérification
select mode, count(*) as voyages, sum(tonnage) as tonnes, min(date) as du, max(date) as au
  from releve_transport where numero like 'TRP-2026-9%' group by mode;
